\label{th1}
\begin{enumerate}[label=(\roman*)] 
\item 
\label{cohoi}
Let $X$ be a smooth variety of dimension $d\geq 1$ over $\mathbb{R}$. If $\mathrm{H}^{d+1}(X(\mathbb{C}),\mathbb{Z})[2]$ vanishes, then $\operatorname{ev}^d_X$ is surjective.
\item 
\label{cohoii}
For all $d\geq 1$, there exists a smooth projective variety $X$ of dimension $d$ over $\mathbb{R}$ such that $\mathrm{H}^{d+1}(X(\mathbb{C}),\mathbb{Z})[2]=0$ and $\operatorname{\overline{ev}}^{d-1}_X$ is not surjective.
\item
\label{cohoiii}
For all $d\geq 2$, there exists a smooth projective variety $X$ of dimension $d$ over $\mathbb{R}$ such that $\operatorname{ev}^d_X$ is not surjective.
\end{enumerate}

