\label{th4}
\begin{enumerate}[label=(\roman*)] 
\item 
\label{exai}
For $d\in\{2,3\}$, there exists a smooth projective variety $X$ of dimension $d$ over~$\mathbb{R}$ such that $\operatorname{ev}^d_{\mathrm{nr},X}$ is not surjective.
\item 
\label{exaii}
Let $X$ be a smooth complete intersection of two quadrics of dimension $d$ over~$\mathbb{R}$ such that $X(\mathbb{R})$ is not connected. If $d\in \{1,2,3\}$, then $\operatorname{\overline{ev}}^{d-1}_{\mathrm{nr},X}$ is not surjective. If~$d\geq 4$, then $\operatorname{ev}^{d-1}_{\mathrm{nr},X}$ is surjective.
\item
\label{exaiii}
Let $X$ be a smooth cubic hypersurface of dimension $d$ over~$\mathbb{R}$ such that~$X(\mathbb{R})$ is not connected. If $d\in\{1,2,3\}$, or if $d=4$ and $X$ is very general, then~$\operatorname{\overline{ev}}^{d-1}_{\mathrm{nr},X}$ is not surjective. If~$d\geq 5$, then~$\operatorname{ev}^{d-1}_{\mathrm{nr},X}$ is surjective.
\item
\label{exaiv}
Let $X$ be an abelian variety of dimension~$d$ over $\mathbb{R}$ such that~$X(\mathbb{R})$ has $2^d$ connected components. If $d\in\{1,2,3\}$, or if $d=4$ and $X$ is principally polarized and very general, then~$\operatorname{\overline{ev}}^{d-1}_{\mathrm{nr},X}$ is not surjective.
\end{enumerate}

