\begin{enumerate}[label=(\roman*), leftmargin=2em] 
\item 
\label{qi}
Fix $d\geq 4$. Does there exist a smooth projective variety $X$ of dimension $d$ over $\mathbb{R}$ such that $\operatorname{ev}^d_{\mathrm{nr},X}$ is not surjective?
\item
\label{qii}
Fix $d\geq 5$. Does there exist a smooth projective variety $X$ of dimension $d$ over~$\mathbb{R}$ such that $\operatorname{\overline{ev}}^{d-1}_{\mathrm{nr},X}$ is not surjective?
