Consider the short exact sequence of $G$-modules 
\begin{equation}
\label{sesGdd+1}
0\to \mathbb{Z}[G]\to\mathbb{Z}(d)\oplus\mathbb{Z}(d+1)\to\mathbb{Z}/2\to0.
\end{equation}
Taking $G$-equivariant cohomology in \eqref{sesGdd+1} and using \eqref{Shapiro} yields an exact sequence
\begin{equation}
\label{lesGdd+1}
\mathrm{H}^{d}_G(X(\mathbb{C}),\mathbb{Z}(d))\oplus\mathrm{H}^{d}_G(X(\mathbb{C}),\mathbb{Z}(d+1))\to\mathrm{H}^{d}_G(X(\mathbb{C}),\mathbb{Z}/2)\to \mathrm{H}^{d+1}(X(\mathbb{C}),\mathbb{Z}).
\end{equation}
As $\mathrm{H}^{d+1}(X(\mathbb{C}),\mathbb{Z})[2]=0$, the right morphism of \eqref{lesGdd+1} vanishes, and hence the left morphism of \eqref{lesGdd+1} is surjective. Now choose an element $\sigma\in \mathrm{H}^0(X(\mathbb{R}),\mathbb{Z}/2)$. By Theorem \ref{thKvH}, there exists a class~$\alpha\in\mathrm{H}^d_G(X(\mathbb{C}),\mathbb{Z}/2)$ such that $\operatorname{\overline{ev}}_{X}^d(\alpha)=\sigma$. Let 
$$(\beta,\gamma)\in \mathrm{H}^{d}_G(X(\mathbb{C}),\mathbb{Z}(d))\oplus\mathrm{H}^{d}_G(X(\mathbb{C}),\mathbb{Z}(d+1))$$
be a lift of $\alpha$ in \eqref{lesGdd+1}. Since the group $\mathrm{H}^d(G,\mathbb{Z}(d+1))$ vanishes and the reduction mod~$2$ morphism $\mathrm{H}^d(G,\mathbb{Z}(d))\to\mathrm{H}^d(G,\mathbb{Z}/2)$ is an isomorphism, we see that~$\operatorname{ev}_X^d(\beta)=\sigma$. This proves the proposition.

Using the long exact sequence of $G$-equivariant cohomology of the pair of $G$\nobreakdash-spaces $(Y(\mathbb{C}),X(\mathbb{C}))$, one reduces to proving the vanishing of $\mathrm{H}^j_G(Y(\mathbb{C}),X(\mathbb{C}),M)$ for $j\leq d$. We prove it, for all $M$, by induction on $j$. Let $f:Y(\mathbb{C})\setminus X(\mathbb{C})\hookrightarrow Y(\mathbb{C})$ be the inclusion. Applying \eqref{rcles} to $\mathcal{F}:=f_!M$ yields an exact sequence
\begin{equation}
\label{realcomplex}
\mathrm{H}_G^{j-1}(Y(\mathbb{C}),X(\mathbb{C}),M(1))\to\mathrm{H}_G^j(Y(\mathbb{C}),X(\mathbb{C}),M)\to\mathrm{H}^j(Y(\mathbb{C}),X(\mathbb{C}),M).
\end{equation}
The left term of \eqref{realcomplex} vanishes by the induction hypothesis. By Sommese's weak Lefschetz theorem (see \cite[Theorem~7.1.1]{lazarsfeldPositivityII} whose proof applies
with coefficients in any abelian group $M$), the group $\mathrm{H}^j(Y(\mathbb{C}),X(\mathbb{C}),M)$ vanishes because~$j\leq d$. The middle term of \eqref{realcomplex} therefore vanishes and the proof is complete.

\label{prop:image_global_sign_hypersurface}
Let $X\subset \mathbb{P}_\mathbb{R}^{c+d}$ be a smooth complete intersection of codimension~$c$. Fix $0\leq j\leq d-1$. Then the image of $\operatorname{\overline{ev}}^j_X$ is generated by $1\in \mathrm{H}^0(X(\mathbb{R}),\mathbb{Z}/2)$.

In particular, if $X(\mathbb{R})$ is not connected, then $\operatorname{\overline{ev}}^j_X$ is not surjective.

Set $Y:=\mathbb{P}^{c+d}_{\mathbb{R}}$. Consider the commutative diagram
\begin{equation*}
\label{diagoev}
\begin{tikzcd}[row sep=small, column sep=normal]
	{\mathrm{H}_G^{j}(Y(\mathbb{C}),\mathbb{Z}/2)}&{\mathrm{H}^0(Y(\mathbb{R}),\mathbb{Z}/2)} \\
	{\mathrm{H}_G^{j}(X(\mathbb{C}),\mathbb{Z}/2)} &{\mathrm{H}^0(X(\mathbb{R}),\mathbb{Z}/2)}
	\arrow["{\operatorname{\overline{ev}}^j_{Y}}", from=1-1, to=1-2]
	\arrow["\rotatebox{90}{$\sim$}"', from=1-1, to=2-1]
	\arrow[from=1-2, to=2-2]
	\arrow["{\operatorname{\overline{ev}}^j_{X}}", from=2-1, to=2-2]
\end{tikzcd}
\end{equation*}
whose vertical arrows are restriction maps. The left vertical arrow is bijective for~$j\leq d-1$ by Proposition \ref{prop:weak_lefschetz}. The image of~$\operatorname{\overline{ev}}^j_X$ is therefore included in the image of $\mathrm{H}^0(Y(\mathbb{R}),\mathbb{Z}/2)\to \mathrm{H}^0(X(\mathbb{R}),\mathbb{Z}/2)$. As $Y(\mathbb{R})$ is connected, this shows that the image of $\operatorname{\overline{ev}}^j_X$ is included in the subgroup generated by $1$ (hence equal to it as one sees by considering the classes in the image of $\mathrm{H}^j_G(\operatorname{pt},\mathbb{Z}/2)\to \mathrm{H}^j_G(X(\mathbb{C}),\mathbb{Z}/2)$).

We assume that $j\geq d$ (if not, replace $j$ with $2d-j-1$). Consider the~diagram
\vspace{-10pt}
\begin{equation*}
\begin{tikzcd}[row sep=small, column sep=small]
	0 & {\mathrm{H}_{G,X(\mathbb{R})}^j(X(\mathbb{C}),\mathbb{Z}/2)} & {\mathrm{H}_G^j(X(\mathbb{C}),\mathbb{Z}/2)} & {\mathrm{H}_G^j(X(\mathbb{C})\setminus X(\mathbb{R}),\mathbb{Z}/2)} & 0\\
	& \bigoplus_{i=0}^{j-d}\mathrm{H}^i(X(\mathbb{R}),\mathbb{Z}/2)& \mathrm{H}^*(X(\mathbb{R}),\mathbb{Z}/2)& &
	\arrow[from=1-1, to=1-2]
	\arrow[from=1-2, to=1-3]
	\arrow[from=1-3, to=1-4]
        \arrow["\tau"'{xshift=7pt},shift right, curve={height=5pt}, yshift=0pt, start anchor={[xshift=12pt]}, end anchor={[xshift=-16pt]}, from=1-4, to=1-3]
        	\arrow[from=1-4, to=1-5]
	\arrow[equals, from=1-2, to=2-2]
	\arrow["r_X^j", from=1-3, to=2-3]
	\arrow["\smile w_X"{yshift=1.5pt}, from=2-2, to=2-3]
\end{tikzcd}
\end{equation*}
whose top row is the exact sequence of \cite[Proposition 1.3]{benoistIntegralHodgeConjecture2020}, where~$\tau$ is the section induced by the canonical splitting described in \cite[Proof of Proposition~1.3]{benoistIntegralHodgeConjecture2020} and whose left vertical equality stems from equivariant purity \cite[(1.20)]{benoistIntegralHodgeConjecture2020} and the canonical decomposition \cite[(1.26)]{benoistIntegralHodgeConjecture2020}. 

The square commutes by \cite[(1.39) and Remark 1.6\,(i)]{benoistIntegralHodgeConjecture2020}. It follows~that
\begin{equation}
\label{rj1}
r_X^j(\mathrm{H}_{G,X(\mathbb{R})}^j(X(\mathbb{C}),\mathbb{Z}/2))=\Big( \bigoplus_{i=0}^{j-d}\mathrm{H}^i(X(\mathbb{R}),\mathbb{Z}/2)\Big)\smile w_X.
\end{equation}
For $k\in\mathbb{Z}$, let $z_k:\mathrm{H}^k_G(X(\mathbb{C})\setminus X(\mathbb{R}),\mathbb{Z}/2)\to \bigoplus_{i=k-d+1}^{k}\mathrm{H}^i(X(\mathbb{R}),\mathbb{Z}/2)$ be the map called $w_k$ in \cite[p.\,25]{benoistIntegralHodgeConjecture2020} (we change notation to avoid confusion with the Stiefel--Whitney classes $w_{i,X}$ of $X(\mathbb{R})$). The very definitions of the maps $\tau$ and $z_j$ show that $z_j=(\smile w_X^{-1})\circ r_X^j\circ\tau$ 

and hence that 
\begin{equation}
\label{rj2}
\Big(r^j_X\circ\tau(\mathrm{H}_G^j(X(\mathbb{C})\setminus X(\mathbb{R}),\mathbb{Z}/2))\Big)\smile w_X^{-1}=\operatorname{Im}(z_j).
\end{equation}
Combining \eqref{rj1} and \eqref{rj2}, we see that 
\begin{equation}
\label{Rjw-1}
V^j_X\smile w_X^{-1}=\Big(\bigoplus_{i=0}^{j-d}\mathrm{H}^i(X(\mathbb{R}),\mathbb{Z}/2)\Big)\oplus\operatorname{Im}(z_j)
\end{equation}
as subgroups of $\mathrm{H}^*(X(\mathbb{R}),\mathbb{Z}/2)$. 
By \eqref{Rjw-1}, the orthogonal complement of $V^j_X$ with respect to \eqref{Poincare} is exactly the subgroup~$W\subset \bigoplus_{i=0}^{2d-j-1}\mathrm{H}^i(X(\mathbb{R}),\mathbb{Z}/2)$ that is the orthogonal complement of $\operatorname{Im}(z_j)$ with respect to the nondegenerate pairing 
$$\Big(\bigoplus_{i=0}^{2d-j-1}\mathrm{H}^i(X(\mathbb{R}),\mathbb{Z}/2)\Big)\times \Big(\bigoplus_{i=j-d+1}^{d}\mathrm{H}^i(X(\mathbb{R}),\mathbb{Z}/2)\Big)\to \mathbb{Z}/2$$
given by $(x,y)\mapsto \deg(x\smile y)$.

The duality theorem \cite[Theorem 1.12]{benoistIntegralHodgeConjecture2020} implies that the images of $z_j$ and~$z_{2d-j-1}$ are orthogonal complements of each other with respect to the nondegenerate pairing $(x,y)\mapsto \deg(x\smile y\smile w_X)$. We deduce from this fact that $W$ is the image of~$\operatorname{im}(z_{2d-j-1})\smile w_X$ by the projection to $\bigoplus_{i=0}^{2d-j-1}\mathrm{H}^i(X(\mathbb{R}),\mathbb{Z}/2)$. The very definition of $z_{2d-j-1}$ now implies that ${W=V_X^{2d-j-1}}$, as wanted.

\begin{enumerate}[label=(\roman*), leftmargin=2em] 
\item
\label{qui}
When $X$ is Galois maximal, Theorem \ref{thm:image_of_total_restriction_to_the_real_locus} is proved by Kharlamov and R\u{a}sdeaconu in \cite[Propositions 2.6\,(2) and 2.17]{KharlamovRasdeaconu2026}.
\item
\label{quii}
Theorem \ref{thm:image_of_total_restriction_to_the_real_locus} is reminiscent of \cite[Theorem 3.3]{benoistIntegralHodgeConjecture2020} (and both are applications of the duality theorem \cite[Theorem 1.12]{benoistIntegralHodgeConjecture2020}).
\item 
\label{quiii}
It is a matter of pure linear algebra to deduce \cite[Proposition~8.1]{benoistPeriodindexProblemReal2019} from Theorem \ref{thm:image_of_total_restriction_to_the_real_locus}. We think of Theorem \ref{thm:image_of_total_restriction_to_the_real_locus} as a generalization of this proposition, with a more elegant statement.
\item
\label{quiii}
As~$V_X^{d-1}\subset V_X^d$ are exact orthogonal complements with respect to a nondegenerate pairing on~$\mathrm{H}^*(X(\mathbb{R}),\mathbb{Z}/2)$, it follows from Theorem \ref{thm:image_of_total_restriction_to_the_real_locus} that
$$\dim_{\mathbb{Z}/2}(V_X^{d-1})\leq\frac{1}{2}\dim_{\mathbb{Z}/2}(\mathrm{H}^*(X(\mathbb{R}),\mathbb{Z}/2))\leq\dim_{\mathbb{Z}/2}(V_X^{d}).$$
\end{enumerate}

\label{thm:topological_argument_integral_case}
Let $E$ be an elliptic curve over $\mathbb{R}$ such that $E(\mathbb{R})$ is not connected. Let $S$ be an Enriques surface over $\mathbb{R}$. Fix $d\geq 2$ and set~$X:=S\times E^{d-2}$. Then $\operatorname{ev}^d_X$ is surjective if and only if at least one of the following conditions holds:
\begin{enumerate}[label=(\roman*)] 
\item all connected components of $S(\mathbb{R})$ have even Euler characteristic;
\item both halves of $S$ are nonempty.
\end{enumerate}

We proceed in two steps. We freely use the notation introduced in \S\ref{parrestr}.

\begin{Step}
\label{Step1}
Assuming that $S(\mathbb{R})$ has a connected component $\Pi_S$ of odd Euler characteristic and that only one half of $S$ is nonempty, we prove that $\operatorname{ev}^d_X$ is not surjective.
\end{Step}

Let $S'\to S$ be the degree $2$ finite \'etale cover of $S$ by a K3 surface that is surjective at the level of real points. Let $\alpha\in \mathrm{H}^1_G(S(\mathbb{C}),\mathbb{Z}/2)=\mathrm{H}^1_{\textup{\'et}}(S,\mathbb{Z}/2)$ (see \cite{coxEtaleHomotopyType1979} for this isomorphism) be the class of this cover. One has~$[\alpha]_0=0$ in~$\mathrm{H}^0(S(\mathbb{R}),\mathbb{Z}/2)$ because the covering $S'\to S$ is trivial over the points of $S(\mathbb{R})$. In addition, the class~$[\alpha]_1$ is the Borel--Haefliger class of the $2$\nobreakdash-torsion line bundle associated with~$S'\to S$ (see e.g.\,\cite[Lemma 2.1]{benoistPeriodindexProblemReal2019}). As this $2$\nobreakdash-torsion line bundle is nontrivial (because~$S'$ is geometrically connected), it must necessarily be the canonical bundle of~$S$ (because~$S$ is an Enriques surface), and we deduce from \cite[Theorem~3.2.1\,1)]{krasnovCharacteristicClasses1991} that~${[\alpha]_1=w_{1,S}}$ in~$\mathrm{H}^1(S(\mathbb{R}),\mathbb{Z}/2)$. We have shown that $r^1_S(\alpha)=(0,w_{1,S})$.

Applying Theorem \ref{thm:image_of_total_restriction_to_the_real_locus} to $E$ (noting that $w_E=1$ because the tangent bundle is trivial) shows the existence of $\beta\in \mathrm{H}^1_G(E(\mathbb{C}),\mathbb{Z}/2)$ with $r_E^1(\beta)=(0,[E(\mathbb{R})])$, where~$[E(\mathbb{R})]\in \mathrm{H}^1(E(\mathbb{R}),\mathbb{Z}/2)$ is the fundamental class of $E(\mathbb{R})$. (One could also construct $\beta$ directly as the class of an explicit double cover of $E$.)

Let $p:X\to S$ and $(p_i:X\to E)_{1\leq i\leq d-2}$ be the projection maps. Define
$$\gamma:=p^*\alpha\smile p_1^*\beta\smile\dots\smile p_{d-2}^*\beta\quad\text{in }\mathrm{H}^{d-1}_G(X(\mathbb{C}),\mathbb{Z}/2).$$ Let~${q:X(\mathbb{R})\to S(\mathbb{R})}$ and $(q_i:X(\mathbb{R})\to E(\mathbb{R}))_{1\leq i\leq d-2}$ be the projection maps. Set
\begin{equation}
\label{formuladelta}
\delta:=q^*w_{1,S}\smile q_1^*[E(\mathbb{R})]\smile\dots\smile q_{d-2}^*[E(\mathbb{R})]\quad\text{in }\mathrm{H}^{d-1}(X(\mathbb{R}),\mathbb{Z}/2).
\end{equation}
As $r^1_S(\alpha)=(0,w_{1,S})$ and $r_E^1(\beta)=(0,[E(\mathbb{R})])$, the formula \cite[(1.28)]{benoistIntegralHodgeConjecture2020} shows that $r^{d-1}_X(\gamma)=(0,\dots,0,\delta)$ in $\bigoplus_{i=0}^{d-1}\mathrm{H}^i(X(\mathbb{R}),\mathbb{Z}/2)$.

Let $\Pi_E$ be any connected component of $E(\mathbb{R})$, and define $\Pi:= \Pi_S\times(\Pi_E)^{d-2}$. Let~$\sigma \in \mathrm{H}^0(X(\mathbb{R}),\mathbb{Z}/2)$ be the element taking the value $1$ on $\Pi$ and $0$ elsewhere. We claim that $\sigma$ is not in the image of $\operatorname{ev}^d_X$. Assume for contradiction that~${\operatorname{ev}^d_X(\varepsilon)=\sigma}$ for some $\varepsilon\in \mathrm{H}^d_G(X(\mathbb{C}),\mathbb{Z}(d))$. Let $\overline{\varepsilon}\in\mathrm{H}^d_G(X(\mathbb{C}),\mathbb{Z}/2)$ be the reduction mod~$2$ of~$\varepsilon$. It follows from~\mbox{\cite[(1.33)]{benoistIntegralHodgeConjecture2020}} that $[\overline{\varepsilon}]_1=0$. 

The equalities~$([\overline{\varepsilon}]_0,[\overline{\varepsilon}]_1)=(\sigma,0)$ and $r^{d-1}_X(\gamma)=(0,\dots,0,\delta)$,
combined with the fact that~$w_X=q^*w_S$ (because the tangent bundle of $E$ is trivial), show that 
\begin{equation}
\label{triple2}
r_X^d(\overline{\varepsilon})\smile r^{d-1}_X(\gamma)\smile w_X^{-1}=(0,\dots,0,\sigma\delta,q^*w_{1,S}\smile\sigma\delta)
\end{equation}
in $\mathrm{H}^*(X(\mathbb{R}),\mathbb{Z}/2)$. Theorem \ref{thm:image_of_total_restriction_to_the_real_locus} implies that 
\begin{equation}
\label{triple1}
\deg(r_X^d(\overline{\varepsilon})\smile r^{d-1}_X(\gamma)\smile w_X^{-1})=0.
\end{equation}
In view of \eqref{formuladelta}, the degree of the class \eqref{triple2} is equal to $\deg_{\Pi_S}(w_1(\Pi_S)^2)$, that is, to $\chi(\Pi_S)$ mod $2$. Since this degree vanishes by \eqref{triple1}, we deduce that $\Pi_S$ has even Euler characteristic. This is the required contradiction. 

\begin{Step}
Assuming that all connected components of $S(\mathbb{R})$ have even Euler characteristic or that both halves of $S$ are nonempty, we prove that $\operatorname{ev}^d_X$ is surjective.
\end{Step}

As $\operatorname{ev}^1_E$ is surjective by Corollary \ref{corod=1}, it suffices to show that $\operatorname{ev}^2_S$ is surjective. 

We may assume that $S(\mathbb{R})\neq\varnothing$. Set $A:=\{\alpha\in \mathrm{H}^1_G(S(\mathbb{C}),\mathbb{Z}/2)\mid [\alpha]_0=0\}$. The group $\mathrm{H}^1_G(S(\mathbb{C}),\mathbb{Z}/2)$ has four elements, corresponding to the trivial cover~$S\sqcup S\to S$, to the cover $S_{\mathbb{C}}\to S$, and to the two K3 covers of $S$. If both halves of $S$ are nonempty, then $A$ contains only the trivial element. Otherwise, it has two elements: the trivial class and the class $\alpha$ of the K3 cover~$S'\to S$ which is surjective at the level of real points. The latter satisfies $[\alpha]_1=w_{1,S}$ (see Step \ref{Step1}), so~$[\alpha]_1\smile w_{1,S}=0$ if all connected components of $S(\mathbb{R})$ have even Euler characteristic.

Define $B:=\{\beta\in \mathrm{H}^2_G(S(\mathbb{C}),\mathbb{Z}/2)\mid [\beta]_1=0\}$. It follows from \cite[Proposition~8.1]{benoistPeriodindexProblemReal2019} 

that $(\operatorname{\overline{ev}}^2_S)|_B$ is surjective if and only if $[\alpha]_1\smile w_{1,S}=0$ in $\mathrm{H}^2(S(\mathbb{R}),\mathbb{Z}/2)$ for all $\alpha\in A$. By the above, this property is satisfied under our hypothesis on $S$.

Now fix $\sigma\in \mathrm{H}^0(S(\mathbb{R}),\mathbb{Z}/2)$, and choose $\beta\in B$ such that $\operatorname{\overline{ev}}^2_S(\beta)=\sigma$. Consider the exact commutative diagram of $G$-modules
\begin{equation}
\label{commexact}
\begin{tikzcd}[row sep=small, column sep=small]
	{0}&{\mathbb{Z}(3)} & {\mathbb{Z}[G]} & {\mathbb{Z}(2)} & {0} \\
	{0}&{\mathbb{Z}/2} & {\mathbb{Z}/2[G]} & {\mathbb{Z}/2} & {0}
	\arrow[from=1-1, to=1-2]
	\arrow[from=1-2, to=1-3]
	\arrow[from=1-2, to=2-2]
	\arrow[from=1-3, to=1-4]
	\arrow[from=1-3, to=2-3]
	\arrow[from=2-1, to=2-2]
	\arrow[from=2-2, to=2-3]
	\arrow[from=2-3, to=2-4]
	\arrow[from=1-4, to=2-4]
	\arrow[from=1-4, to=1-5]
	\arrow[from=2-4, to=2-5]
\end{tikzcd}
\end{equation}
whose vertical arrows are reduction mod $2$ morphisms. Taking $G$-equivariant cohomology in \eqref{commexact} and using \eqref{Shapiro} yields a commutative exact diagram
\begin{equation}
\label{commexact2}
\begin{tikzcd}[row sep=small, column sep=small]
	{\mathrm{H}^2_G(S(\mathbb{C}),\mathbb{Z}(2))} & {\mathrm{H}^3_G(S(\mathbb{C}),\mathbb{Z}(3))} & {\mathrm{H}^3(S(\mathbb{C}),\mathbb{Z})} \\
	{\mathrm{H}^2_G(S(\mathbb{C}),\mathbb{Z}/2)} & {\mathrm{H}^3_G(S(\mathbb{C}),\mathbb{Z}/2)} & {\mathrm{H}^3(S(\mathbb{C}),\mathbb{Z}/2)}
	\arrow[from=1-1, to=2-1]
	\arrow[from=1-1, to=1-2]
	\arrow[from=1-2, to=1-3]
	\arrow[from=1-2, to=2-2]
	\arrow["\rotatebox{90}{$\sim$}"', from=1-3, to=2-3]
	\arrow[from=2-1, to=2-2]
	\arrow[from=2-2, to=2-3]
\end{tikzcd}
\end{equation}
whose right vertical arrow is an isomorphism because $S$ is an Enriques surface.

Let $\gamma\in \mathrm{H}^3_G(S(\mathbb{C}),\mathbb{Z}/2)$ be the image of $\beta$ in \eqref{commexact2}. We claim that $\gamma$ lifts to a class $\delta\in\mathrm{H}^3_G(S(\mathbb{C}),\mathbb{Z}(3))$ along the middle vertical arrow of \eqref{commexact2}. Taking this claim for granted, diagram \eqref{commexact2} shows that~$\delta$ further lifts to a class $\varepsilon\in \mathrm{H}^2_G(S(\mathbb{C}),\mathbb{Z}(2))$. As 
$$\operatorname{ev}^2_S(\varepsilon)=\operatorname{ev}^3_S(\delta)=\operatorname{\overline{ev}}^3_S(\gamma)=\operatorname{\overline{ev}}^2_S(\beta)=\sigma,$$
this finishes the proof of the theorem.

We now prove the claim. Consider the commutative diagram
\begin{equation}
\label{compositions}
\begin{tikzcd}[row sep=small, column sep=tiny]
	{\mathrm{H}^3_G(S(\mathbb{C}),\mathbb{Z}/2)} & {\mathrm{H}^4_G(S(\mathbb{C}),\mathbb{Z}(3))} & {\mathrm{H}^4_G(S(\mathbb{C}),\mathbb{Z}/2)} & {\mathrm{H}^5_G(S(\mathbb{C}),\mathbb{Z}/2)} \\
	{\mathrm{H}^3_G(S(\mathbb{R}),\mathbb{Z}/2)} & {\mathrm{H}^4_G(S(\mathbb{R}),\mathbb{Z}(3))} & {\mathrm{H}^4_G(S(\mathbb{R}),\mathbb{Z}/2)} & {\mathrm{H}^5_G(S(\mathbb{R}),\mathbb{Z}/2)}\\
	{\mathrm{H}^*(S(\mathbb{R}),\mathbb{Z}/2)} & {\mathrm{H}^1(S(\mathbb{R}),\mathbb{Z}/2)} & {\mathrm{H}^*(S(\mathbb{R}),\mathbb{Z}/2)} & {\mathrm{H}^*(S(\mathbb{R}),\mathbb{Z}/2)}
	\arrow[from=1-1, to=2-1]
	\arrow[from=1-1, to=1-2]
	\arrow[hook, from=1-2, to=1-3]
	\arrow["\sim"', from=1-3, to=1-4]
	\arrow[from=1-2, to=2-2]
	\arrow[from=1-3, to=2-3]
	\arrow[from=2-1, to=2-2]
	\arrow[from=2-2, to=2-3]
	\arrow[from=2-3, to=2-4]
	\arrow["\rotatebox{90}{$\sim$}"', from=1-4, to=2-4]
	\arrow[equal, from=2-1, to=3-1]
	\arrow[equal, from=2-2, to=3-2]
	\arrow[equal, from=2-3, to=3-3]
	\arrow[equal, from=2-4, to=3-4]
\end{tikzcd}
\end{equation}
whose vertical maps are restriction maps, whose vertical equalities are the canonical decompositions \cite[(1.26) and (1.31)]{benoistIntegralHodgeConjecture2020}, and whose horizontal maps are, from left to right, boundary maps associated with $0\to\mathbb{Z}(3)\xrightarrow{2}\mathbb{Z}(3)\to\mathbb{Z}/2\to 0$, reduction mod $2$ morphisms, and boundary maps of ${0\to\mathbb{Z}/2\to\mathbb{Z}/2[G]\to\mathbb{Z}/2\to 0}$. The right vertical arrow of \eqref{compositions} is bijective by \cite[\S 1.1.3]{benoistIntegralHodgeConjecture2020}. The top right horizontal arrow of \eqref{compositions} is bijective by \eqref{rcles} applied with $\mathcal{F}=\mathbb{Z}/2$ since $\mathrm{H}^5(S(\mathbb{C}),\mathbb{Z}/2)=0$ (for dimension reasons) and $\mathrm{H}^4_G(S(\mathbb{C}),\mathbb{Z}/2)\to \mathrm{H}^4(S(\mathbb{C}),\mathbb{Z}/2)=\mathbb{Z}/2$ is onto (it sends the class of a real point to a generator). The top middle horizontal arrow of~\eqref{compositions} is injective because $\mathrm{H}^4_G(S(\mathbb{C}),\mathbb{Z}(3))$ is $2$-torsion. To see it, use \eqref{rcles} with~$\mathcal{F}=\mathbb{Z}(2)$ and note that $\mathrm{H}^4_G(S(\mathbb{C}),\mathbb{Z}(2))\to \mathrm{H}^4(S(\mathbb{C}),\mathbb{Z})=\mathbb{Z}$ is onto (it sends the class of a real point to a generator) and that $\mathrm{H}^5_G(S(\mathbb{C}),\mathbb{Z}(2))\ext@arrow 0359\arrowfill@\relbar\relbar{\setbox\z@\hbox{$\rightarrow$}\dimen0\ht\z@\multiply\dimen0 6\divide\dimen0 10\ht\z@\dimen0\box\z@}{}{\,\sim\,} \mathrm{H}^5_G(S(\mathbb{R}),\mathbb{Z}(2))$ is $2$-torsion (combine \cite[\S 1.1.3 and (1.31)]{benoistIntegralHodgeConjecture2020}).

As $[\beta]_1=0$, it follows from \cite[\S 1.2.4]{benoistIntegralHodgeConjecture2020} that $[\gamma]_1=0$. The composition $\mathrm{H}^3_G(S(\mathbb{R}),\mathbb{Z}/2)\to \mathrm{H}^4_G(S(\mathbb{R}),\mathbb{Z}/2)$ of the bottom left horizontal arrows of \eqref{compositions} is the boundary map associated with~$0\to\mathbb{Z}/2\xrightarrow{}\mathbb{Z}/4(3)\to\mathbb{Z}/2\to 0$, and hence is the sum of the Bockstein and of the boundary map of ${0\to\mathbb{Z}/2\to\mathbb{Z}/2[G]\to\mathbb{Z}/2\to 0}$ (see \cite[\S 2.2]{benoistPeriodindexProblemReal2019}). 
It now follows from \cite[(2.8)]{benoistPeriodindexProblemReal2019} and \cite[\S 1.2.4]{benoistIntegralHodgeConjecture2020} that the composition of the three bottom horizontal arrows of \eqref{compositions} is given, at the level of the canonical decompositions, by the formula $(a_0,a_1,a_2)\mapsto (0,a_1,a_1^2)$ (where~$a_i\in \mathrm{H}^i(S(\mathbb{R}),\mathbb{Z}/2)$). Since $[\gamma]_1=0$, we deduce that $\gamma$ is mapped to zero in the bottom right group of~\eqref{compositions}. Diagram \eqref{compositions} therefore shows that $\gamma$ is mapped to zero in $\mathrm{H}^4_G(S(\mathbb{C}),\mathbb{Z}(3))$ and hence that it lifts to a class $\delta\in\mathrm{H}^3_G(S(\mathbb{C}),\mathbb{Z}(3))$.

\label{corEnriques}
Let $S$ be an Enriques surface over $\mathbb{R}$. Then $\operatorname{ev}^2_S$ is surjective if and only if at least one of the following conditions holds:
\begin{enumerate}[label=(\roman*)] 
