	\arrow[from=1-1, to=1-2]
	\arrow["\alpha"',shift right=2, from=1-2, to=1-3]
	\arrow["\beta"',from=1-3, to=1-2]
	\arrow["{\operatorname{sign}_{n,X}^c}"', from=1-2, to=2-2]
	\arrow["{j^*}"',shift right=2, from=1-3, to=1-4]
	\arrow["\sigma"',from=1-4, to=1-3]
