	\arrow[from=2-1, to=2-2]
	\arrow["{\alpha'}", shift left=2, from=2-2, to=2-3]
	\arrow["\beta'",from=2-3, to=2-2]
	\arrow["{j(\mathbb{R})^*}",shift left=2, from=2-3, to=2-4]
	\arrow["\sigma'",from=2-4, to=2-3]
	\arrow[from=2-4, to=2-5]
\end{tikzcd}}
\]
the left outer square and the right inner and outer squares commute by functoriality of higher signature morphisms. A diagram chase then shows that the left inner square also commutes. This completes the proof of the lemma.

Suppose first that $n\geq c$. Applying $c$ times Lemma \ref{lem:P1_suspension_image_quadratic_real_cycle_class_map} shows that $\operatorname{sign}_{n-c,Y}^0$ is a retract of $\operatorname{sign}_{n,X}^c$. Since the cokernel of $\operatorname{sign}_{n-c,Y}^0$ is not killed by $2^{d-n-1}$, we deduce that the cokernel of $\operatorname{sign}_{n,X}^c$ is not killed by $2^{d-n-1}$, as required.

Suppose now that $n<c$. Iterating Lemma~\ref{lem:P1_suspension_image_quadratic_real_cycle_class_map} yields a surjective~morphism
$$\theta:\mathrm{H}^c(X(\mathbb{R}),\mathbb{Z})\to\mathrm{H}^0(Y(\mathbb{R}),\mathbb{Z})$$
satisfying $\theta\bigl(\operatorname{Im}(\operatorname{sign}_{c,X}^c)\bigr)=\operatorname{Im}(\operatorname{sign}_{0,Y}^0)$ (to be precise, the morphism $\theta$ is the composition of $c$ of the morphisms $\beta'$ from Lemma~\ref{lem:P1_suspension_image_quadratic_real_cycle_class_map}). By \cite[(2-4)]{lerbetImageHigherSignature2026}, the inclusion $\mathbf{I}^c\subseteq\mathbf{I}^n$ induces a commutative~square
\begin{equation}
\label{signsignnc}
\begin{tikzcd}[row sep=small]
	{\mathrm{H}^c(X,\mathbf{I}^c)} & {\mathrm{H}^c(X,\mathbf{I}^n)} \\
	{\mathrm{H}^c(X(\mathbb{R}),\mathbb{Z})} & {\mathrm{H}^c(X(\mathbb{R}),\mathbb{Z})}
	\arrow[two heads, from=1-1, to=1-2]
	\arrow["{\operatorname{sign}_{c,X}^c}"', from=1-1, to=2-1]
	\arrow["{\,\operatorname{sign}_{n,X}^c}", from=1-2, to=2-2]
	\arrow["{\cdot 2^{c-n}}"', from=2-1, to=2-2]
\end{tikzcd}
\end{equation}
whose top horizontal arrow is surjective (see e.g.\,\cite[Lemma~2.6]{lerbetWittGroupsSmooth2026}). It follows from diagram~\eqref{signsignnc} and from the equality $\theta\bigl(\operatorname{Im}(\operatorname{sign}_{c,X}^c)\bigr)=\operatorname{Im}(\operatorname{sign}_{0,Y}^0)$ that
\begin{equation}
\label{thetasign}
\theta\bigl(\operatorname{Im}(\operatorname{sign}_{n,X}^c)\bigr)=2^{c-n}\,\theta\bigl(\operatorname{Im}(\operatorname{sign}_{c,X}^c)\bigr)=2^{c-n}\operatorname{Im}(\operatorname{sign}_{0,Y}^0).
\end{equation}

Since the cokernel of ${\operatorname{sign}_{0,Y}^0:\mathrm{W}_{\mathrm{nr}}(Y)\to\mathrm{H}^0(Y(\mathbb{R}),\mathbb{Z})}$ is not killed by $2^{d-c-1}$ and~$\mathrm{H}^0(Y(\mathbb{R}),\mathbb{Z})$ is torsion free, the cokernel of ${2^{c-n}\,\operatorname{sign}_{0,Y}^0}$ is not killed by $2^{d-n-1}$.
It follows from \eqref{thetasign} that $\mathrm{H}^0(Y(\mathbb{R}),\mathbb{Z})/\theta\bigl(\operatorname{Im}(\operatorname{sign}_{n,X}^c)\bigr)$ is not killed by $2^{d-n-1}$. As~$\theta$ is surjective, we deduce that the cokernel of~$\operatorname{sign}_{n,X}^c$ is not killed by~$2^{d-n-1}$.
